<script>
function editAward(encoded){var item=JSON.parse(atob(encoded)),form=document.getElementById('awardForm');form.action=@json(route('organization.update',['award-types','__ID__'])).replace('__ID__',item.id);document.getElementById('awardMethod').innerHTML='<input type="hidden" name="_method" value="PUT">';form.elements.name.value=item.name||'';form.elements.description.value=item.description||'';form.elements.status.value=Number(item.status)?'1':'0';document.getElementById('awardFormTitle').textContent='Edit Award Type';document.getElementById('awardFormHelp').textContent='Update the award type details';document.getElementById('awardSubmit').textContent='Update Award Type';document.getElementById('awardCancel').style.display='';form.scrollIntoView({behavior:'smooth',block:'start'})}
function resetAwardForm(){var form=document.getElementById('awardForm');form.reset();form.action=@json(route('organization.store','award-types'));document.getElementById('awardMethod').innerHTML='';document.getElementById('awardFormTitle').textContent='Add New Award Type';document.getElementById('awardFormHelp').textContent='Fill in the details to create a new award type';document.getElementById('awardSubmit').textContent='Add Award Type';document.getElementById('awardCancel').style.display='none'}
function toggleAwardDescription(button){var description=button.previousElementSibling,open=!description.classList.contains('collapsed');description.classList.toggle('collapsed');button.textContent=open?'⌄ Show more':'⌃ Show less'}
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.award-confirm').forEach(function(form){form.addEventListener('submit',function(event){if(form.dataset.confirmed)return;event.preventDefault();Swal.fire({title:form.dataset.message,icon:'warning',showCancelButton:true,confirmButtonColor:'#00b783'}).then(function(result){if(result.isConfirmed){form.dataset.confirmed='1';form.submit()}})})});@if($errors->any())document.getElementById('awardForm').scrollIntoView();@endif});
</script>
